// QWidget * QSplitter::replaceWidget(int index, QWidget * widget) (test from the overlay)
func TestOwnership_QSplitter_ReplaceWidget(t *testing.T) {
	goqt.Run(t, func() {
		sp := qtwidgets.NewQSplitter(nil)
		old := qtwidgets.NewQLabelWithText("old", nil)
		sp.AddWidget(old)
		repl := qtwidgets.NewQLabelWithText("new", nil)
		got := sp.ReplaceWidget(0, repl)
		if got != old.AsQWidget() || old.Ownership() != qtcore.Owned {
			t.Errorf("replaced widget: %v, want Owned", old.Ownership())
		}
		if repl.Ownership() != qtcore.Parented {
			t.Errorf("new widget: %v, want Parented", repl.Ownership())
		}
		sp.Delete()
		if repl.Alive() || !old.Alive() {
			t.Errorf("after delete: new alive=%v old alive=%v", repl.Alive(), old.Alive())
		}
		old.Delete()
	})
}

